tool.command:
## SURVIVOR cannot read compressed VCFs and keys samples on list order, so
## stage every input as plain text under a predictable name. Two things in
## SURVIVOR 1.0.7 give wrong results without an error, so staging also guards
## against them: a record whose INFO starts with SVLEN= or END= can be dropped
## or mis-sized (those fields are moved behind the others; SURVIVOR writes its
## own INFO, so this never shows in the output), and a multi-sample input is
## collapsed to one column with genotypes taken from the wrong sample.
set -o pipefail &&
#for $i, $vcf in enumerate($input_vcfs):
    #if $vcf.is_of_type('vcf_bgzip'):
        gzip -dc '$vcf'
    #else:
        cat '$vcf'
    #end if
    | awk -v input='${i + 1}' '
        BEGIN { FS = OFS = "\t" }
        substr(\$0, 1, 1) == "\043" {
            if (index(\$0, "\043CHROM") == 1 && NF > 10) {
                print "Input " input " has " (NF - 9) " sample columns. SURVIVOR merge needs one sample per input; split multi-sample VCFs first." > "/dev/stderr";
                exit 1
            }
            print;
            next
        }
        {
            n = split(\$8, field, ";");
            head = "";
            tail = "";
            for (j = 1; j <= n; j++) {
                if (field[j] ~ /^(SVLEN|END)=/) { tail = tail ";" field[j] } else { head = head ";" field[j] }
            }
            if (head != "" && tail != "") { \$8 = substr(head, 2) tail }
            print
        }' > 'input_${i}.vcf' &&
    echo 'input_${i}.vcf' >> vcf_list.txt &&
#end for

SURVIVOR merge
    vcf_list.txt
    #if $distance.distance_type == 'fraction':
        $distance.max_distance_fraction
    #else:
        $distance.max_distance_bp
    #end if
    $min_support
    $same_type
    $same_strand
    ## size-based distance estimation is hard-disabled in SURVIVOR 1.0.7, so the flag is ignored
    0
    $min_size
    '$merged_vcf'
